// Get all incoming items
const items = $input.all();

// Extract query from the first item, or use an empty object
const q = (items[0] && items[0].json && items[0].json.query) ? items[0].json.query : {};

// Safely parse and default parameters
const search = (q.search || " ").trim(); // Ensure it's always a string
const limit = Number.isInteger(parseInt(q.pageSize)) ? parseInt(q.pageSize) : 100000;
const pageNo = Number.isInteger(parseInt(q.pageNo)) ? parseInt(q.pageNo) : 1;
const offset = (pageNo - 1) * limit;

// Return a single item with params for the next node
return [
  {
    json: {
      params: {
        search,
        limit,
        offset
      }
    }
  }
];

return $input.all().map(item => {
  const data = item.json;
  const imageBuffer = Buffer.from(data.vendor_icon_content.data);
  const imageType = data.vendor_icon_type || 'jpeg';
  const base64Image = imageBuffer.toString('base64');

  // Generate filename
  const filename = `vendor_${data.vendor_id}.${imageType}`;

  return {
    json:  {  // 'data' is the standard expected binary property name
        data: base64Image,
        mimeType: `image/${imageType}`,
        fileName: filename
      }
  };
});

const keysToRemove = ['vendor_icon_content', 'vendor_icon_type'];

return $input.all().map(item => {
  const json = {...item.json};
  keysToRemove.forEach(k => delete json[k]);

  json.filename = `http://192.168.0.7:5678/webhook/image?filename=vendor_${item.json.vendor_id}.${item.json.vendor_icon_type || 'jpeg'}`;

  return { json };
});

// Get incoming data from POST body
const items = $input.all();
const body = (items[0] && items[0].json && items[0].json.body) ? items[0].json.body : {};

// Extract vendor ID from body
const vendorId = parseInt(body.vendor_id || body.vendorId || body.id) || 0;

// Validate
if (!vendorId) {
  throw new Error('Vendor ID is required in request body');
}

return [
  {
    json: {
      params: {
        id: vendorId
      }
    }
  }
];

const result = $input.first().json;
if (result && result.vendor_id) {
  return [{ json: { success: true, message: 'Vendor deleted successfully' } }];
}
return [{ json: { success: false, message: 'Vendor not found or could not be deleted' } }];

const data = $input.first().json;
const vendorStats = data.vendor_stats || {};
const orderStats = data.order_stats || {};
const topVendor = data.top_vendor || {};
const recentPurchase = data.recent_purchase || {};

const total = parseInt(vendorStats.total_vendors || 0);
const withIcon = parseInt(vendorStats.vendors_with_icon || 0);
const withWebsite = parseInt(vendorStats.vendors_with_website || 0);
const withEmail = parseInt(vendorStats.vendors_with_email || 0);

return [{
  json: {
    summary: {
      totalVendors: total,
      vendorsWithIcon: withIcon,
      vendorsWithWebsite: withWebsite,
      vendorsWithEmail: withEmail
    },
    completeness: {
      iconCompletion: total > 0 ? Math.round((withIcon / total) * 100) : 0,
      websiteCompletion: total > 0 ? Math.round((withWebsite / total) * 100) : 0,
      emailCompletion: total > 0 ? Math.round((withEmail / total) * 100) : 0
    },
    purchases: {
      totalOrders: parseInt(orderStats.total_orders || 0),
      totalSpent: parseFloat(orderStats.total_spent || 0),
      lastOrderDate: orderStats.last_order_date || null
    },
    topVendor: {
      vendorId: topVendor.vendor_id || null,
      vendorName: topVendor.vendor_name || null,
      orderCount: parseInt(topVendor.order_count || 0),
      totalSpent: parseFloat(topVendor.total_spent || 0),
      vendorIcon: topVendor.vendor_icon || null
    },
    recentPurchase: {
      vendorName: recentPurchase.vendor_name || null,
      orderDate: recentPurchase.order_date || null,
      totalCost: parseFloat(recentPurchase.total_cost || 0),
      vendorIcon: recentPurchase.vendor_icon || null
    }
  }
}];

const data = $input.first().json;
return [{ 
  json: { 
    success: true, 
    message: 'Vendor created successfully', 
    vendor: data 
  } 
}];
